import json
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
MOCK_RECORDS = PROJECT_ROOT / "data" / "mock_records.json"


def execute_lookup_status(params: dict) -> dict:
    try:
        with open(MOCK_RECORDS, "r", encoding="utf-8") as f:
            records = json.load(f)
    except (OSError, json.JSONDecodeError):
        return {"found": False}

    rt = params.get("record_type")
    ident = str(params.get("identifier", "")).strip()

    # Format generated by setup_phase0.py / generate_more_data.py:
    #   [{"id": "TKT-1001", "status": "Open", "subject": "..."}, ...]
    if isinstance(records, list):
        if rt == "ticket_status":
            for rec in records:
                if str(rec.get("id", "")).lower() == ident.lower():
                    return {"found": True, "result": rec}
        return {"found": False}

    # Format documented in AGENTS.md Section 3:
    #   {"ticket_status": {"4521": "in_progress"}, "stipend_eligibility": {...}}
    if rt in records and ident in records[rt]:
        return {"found": True, "result": records[rt][ident]}
    return {"found": False}
